// Installed-package consumer probe for Test-LedgerPackageConsumer.ps1. It references only the restored
// ResourceManager.Ledger package and the identity generated by the packaged ledger-build tool, opens the Native
// library built from the packaged source archive, and records each passing case by name.
using System.Buffers;
using System.Runtime.InteropServices;
using System.Text.Json;
using ResourceManager.Ledger;
using ResourceManager.Ledger.Generated;
using ResourceManager.Ledger.Identity;

string nativePath = args[0];
bool statisticsExpected = args[1] == "1";
string resultPath = args[2];
var cases = new List<string>();
string? failure = null;
try
{
    // A local copy: the generated width is a constant, and branching on it directly is unreachable code here.
    int width = LedgerOwnerBuild.UidWidthBits;
    if (width == 256) await Run<LedgerUid256>();
    else await Run<LedgerUid128>();
}
catch (Exception exception)
{
    failure = exception.ToString();
    Console.Error.WriteLine(exception);
}
var result = new Dictionary<string, object?>
{
    ["passed"] = failure is null,
    ["uidWidthBits"] = (int)LedgerOwnerBuild.UidWidthBits,
    ["developmentAllocationStatistics"] = statisticsExpected,
    ["cases"] = cases,
    ["failure"] = failure,
};
File.WriteAllText(resultPath, JsonSerializer.Serialize(result, new JsonSerializerOptions { WriteIndented = true }) + "\n");
Console.WriteLine(failure is null ? $"PASS {cases.Count} package-consumer cases" : "FAIL after " + cases.Count + " cases");
return failure is null ? 0 : 1;

void Check(bool condition, string name)
{
    if (!condition) throw new InvalidOperationException("Case failed: " + name);
    cases.Add(name);
    Console.WriteLine("PASS " + name);
}

async Task Run<TUid>() where TUid : unmanaged, ILedgerUid<TUid>
{
    TUid Key(byte key)
    {
        byte[] bytes = Enumerable.Range(1, TUid.ByteLength).Select(value => unchecked((byte)(31 * value))).ToArray();
        bytes[^1] = key;
        return TUid.FromBytes(bytes);
    }

    var owner = LedgerOwner<TUid>.Open(nativePath, LedgerOwnerBuild.Identity);
    Check(owner.TableCount == 2 && TUid.ByteLength * 8 == LedgerOwnerBuild.UidWidthBits, "open_validated_identity");
    Check(NoFaultControls(nativePath), "production_native_without_fault_controls");

    TUid a = Key(1);
    LedgerPushResult<TUid> pushed = owner.Push(LedgerTarget<TUid>.ForTable(0), a, 64);
    Check(pushed.Status == LedgerStatus.NewlyAllocated && pushed.Lease is { IsLoading: true, Length: 64 }, "push_new_allocation");
    using (LedgerLease<TUid> loading = pushed.Lease!)
    {
        loading.Span.Fill(0x5a);
        loading.PublishOnDispose();
    }

    LedgerUseResult<TUid> used = owner.Use(a);
    Check(used.Status == LedgerStatus.InMemory && used.Lease!.Span[63] == 0x5a, "use_published_region");
    LedgerLease<TUid> lease = used.Lease!;
    Check(owner.Close(a) == LedgerStatus.InUse, "close_while_held_is_in_use");
    LedgerEndResult ended = await lease.EndUseAsync();
    Check(ended.Status == LedgerStatus.Completed && ended.HasEnded && lease.HasEnded, "end_use_async_completes");
    Check(lease.TryTakeEndResult(out LedgerEndResult taken) && taken.Status == LedgerStatus.Completed &&
        !lease.TryTakeEndResult(out _), "end_result_taken_once");

    LedgerUseResult<TUid> pinnedUse = owner.Use(a);
    ValueTask ending;
    {
        LedgerLease<TUid> pinnedLease = pinnedUse.Lease!;
        using MemoryHandle pin = pinnedLease.GetMemoryChunk(0, 32).Pin();
        ending = pinnedLease.DisposeAsync();
        Check(!ending.IsCompleted && owner.Close(a) == LedgerStatus.InUse, "pinned_end_waits_for_unpin");
    }
    await ending;

    _ = owner.Tick();
    LedgerUseResult<TUid> afterTick = owner.Use(a);
    Check(afterTick.Status == LedgerStatus.InMemory, "region_survives_tick_after_use");
    using (afterTick.Lease!) { }
    Check(owner.GetTableView(0).SystemPageBytes > 0, "table_view_reports_pages");

    TUid b = Key(2);
    LedgerPushResult<TUid> abandonedPush = owner.Push(LedgerTarget<TUid>.ForTable(1), b, 32);
    LedgerEndResult abandoned = await abandonedPush.Lease!.AbandonAsync();
    LedgerUseResult<TUid> afterAbandon = owner.Use(b);
    Check(abandonedPush.Status == LedgerStatus.NewlyAllocated && abandoned.Status == LedgerStatus.Abandoned &&
        afterAbandon.Status != LedgerStatus.InMemory && afterAbandon.Lease is null, "abandoned_load_never_published");

    int notices = 0;
    using (LedgerSubscription<TUid> subscription = owner.Subscribe(0, _ => notices++))
    {
        Check(subscription.Table == 0 && !subscription.IsDisposed, "subscription_registered");
    }

    Check(owner.ForceRelease(a) == LedgerStatus.Ok && owner.GetTableView(0).SystemPageBytes == 0, "force_release_returns_pages");

    if (statisticsExpected)
    {
        LedgerDevelopmentStatistics statistics = owner.GetDevelopmentStatistics(0);
        Check(owner.DevelopmentStatisticsAvailable && statistics.NewAllocations >= 1, "development_allocation_statistics");
    }
    else
    {
        bool unavailable = false;
        try { _ = owner.GetDevelopmentStatistics(0); } catch (NotSupportedException) { unavailable = true; }
        Check(!owner.DevelopmentStatisticsAvailable && unavailable, "development_allocation_statistics");
    }

    // An abandoned load leaves its page cleanup to the owner: normal destroy reports it until a Close settles it.
    Check(owner.Destroy() == LedgerStatus.CleanupPending && !owner.IsDestroyed && owner.Close(b) == LedgerStatus.Ok &&
        owner.Destroy() == LedgerStatus.Ok && owner.IsDestroyed, "destroy_after_pending_cleanup");
    owner.Dispose();
}

static bool NoFaultControls(string path)
{
    nint library = NativeLibrary.Load(path);
    try { return !NativeLibrary.TryGetExport(library, "rm_ledger_test_fail_release", out _); }
    finally { NativeLibrary.Free(library); }
}
